-- VIOLATES 3NF (Transitive dependency: zip_code -> city, state):
-- CREATE TABLE users (id INT, zip_code VARCHAR(10), city VARCHAR(50), state VARCHAR(50));

-- SATISFIES 3NF (Separated into zip_codes reference table):
CREATE TABLE zip_codes (
  zip_code VARCHAR(10) PRIMARY KEY,
  city VARCHAR(50) NOT NULL,
  state VARCHAR(50) NOT NULL
);

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  zip_code VARCHAR(10),
  FOREIGN KEY (zip_code) REFERENCES zip_codes(zip_code)
);

-- Atomicity:  Rolls back via Undo Log on failure
-- Consistency: Enforces FOREIGN KEY & NOT NULL constraints
-- Isolation:  MVCC read-views isolate concurrent transactions
-- Durability: Redo Log flushes to disk before COMMIT returns!

START TRANSACTION;
UPDATE accounts SET balance = balance - 500 WHERE id = 1;
UPDATE accounts SET balance = balance + 500 WHERE id = 2;
COMMIT;

START TRANSACTION;

-- Debit Account A
UPDATE accounts SET balance = balance - 100 WHERE id = 1;

-- Credit Account B
UPDATE accounts SET balance = balance + 100 WHERE id = 2;

-- Check if errors occurred
-- If success:
COMMIT;
-- If error:
-- ROLLBACK;

// N+1 PROBLEM (101 Database Queries!):
const users = await db.query('SELECT * FROM users LIMIT 100'); // 1 query
for (const user of users) {
  // Executed 100 times in loop!
  user.orders = await db.query('SELECT * FROM orders WHERE user_id = ?', [user.id]);
}

// FIXED WITH BATCH IN (2 Database Queries Total!):
const users = await db.query('SELECT * FROM users LIMIT 100'); // 1 query
const userIds = users.map(u => u.id);
const allOrders = await db.query('SELECT * FROM orders WHERE user_id IN (?)', [userIds]); // 2nd query!

CREATE TABLE users (
  id INT AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(255) NOT NULL UNIQUE,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE orders (
  id INT AUTO_INCREMENT PRIMARY KEY,
  user_id INT NOT NULL,
  total_amount DECIMAL(10,2) NOT NULL,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB;

-- Create secondary index on email
CREATE INDEX idx_users_email ON users(email);

-- Covering Index Query: Index contains both email and PK id!
-- EXPLAIN shows 'Using index' (No table lookup required!)
SELECT id, email FROM users WHERE email = 'alex@example.com';

CREATE INDEX idx_status_created_user ON orders(status, created_at, user_id);

-- USES INDEX (Leftmost prefix status matched!):
SELECT * FROM orders WHERE status = 'completed' AND created_at > '2026-01-01';

-- CANNOT USE INDEX (Missing status leftmost column!):
SELECT * FROM orders WHERE user_id = 42;

-- Set isolation level for current session
SET SESSION TRANSACTION ISOLATION LEVEL READ COMMITTED;

START TRANSACTION;
SELECT balance FROM accounts WHERE id = 1;
COMMIT;

-- Reset to MySQL default:
SET SESSION TRANSACTION ISOLATION LEVEL REPEATABLE READ;

const mysql = require('mysql2/promise');

// Create connection pool instance
const pool = mysql.createPool({
  host: 'localhost',
  user: 'db_user',
  password: 'secret_password',
  database: 'app_db',
  waitForConnections: true,
  connectionLimit: 10, // Max 10 active connections
  queueLimit: 0
});

async function getUsers() {
  // Automatically acquires connection from pool and releases it when finished!
  const [rows] = await pool.query('SELECT id, name FROM users WHERE is_active = 1');
  return rows;
}

-- NON-SARGABLE (Prevents index usage on created_at!):
SELECT * FROM orders WHERE YEAR(created_at) = 2026;

-- REFACTORED SARGABLE (Uses B-Tree index on created_at!):
SELECT * FROM orders 
WHERE created_at >= '2026-01-01 00:00:00' 
  AND created_at <  '2027-01-01 00:00:00';
